fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Cast to i16 to avoid overflow when subtracting and taking abs
    let diff = (a as i16) - (b as i16);
    let tol = tol as i16;
    diff.abs() < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assume a.len() == b.len() and tol > 0 as per problem statement
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}